  resizeImage: "SHIFT \u0927\u0930\u0942\u0928 \u0924\u0941\u092E\u094D\u0939\u0940 \u092E\u0941\u0915\u094D\u0924\u092A\u0923\u0947 \u0906\u0915\u093E\u0930 \u092E\u094B\u0920\u093E \u091B\u094B\u091F\u093E \u0915\u0930\u0941 \u0936\u0915\u0924\u093E,\n\u0915\u0947\u0902\u0926\u094D\u0930\u093E\u092A\u093E\u0938\u0942\u0928 \u0906\u0915\u093E\u0930 \u092E\u094B\u0920\u093E \u091B\u094B\u091F\u093E \u0915\u0930\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940 ALT \u0927\u0930\u0942\u0928 \u0920\u0947\u0935\u093E",
  rotate: "\u092B\u093F\u0930\u0935\u0924 \u0905\u0938\u0924\u093E\u0928\u093E \u0936\u093F\u092B\u094D\u091F \u0927\u0930\u0942\u0928 \u0924\u0941\u092E\u094D\u0939\u0940 \u0915\u094B\u0928 \u092E\u0930\u094D\u092F\u093E\u0926\u093F\u0924 \u0915\u0930\u0942 \u0936\u0915\u0924\u093E",
  lineEditor_info: "\u092A\u0949\u0907\u0902\u091F \u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0915\u0930\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940 CtrlOrCmd \u0926\u093E\u092C\u0942\u0928 \u0920\u0947\u0935\u0941\u0928 \u0921\u092C\u0932-\u0915\u094D\u0932\u093F\u0915 \u0915\u0930\u093E \u0915\u093F\u0902\u0935\u093E CtrlOrCmd + Enter \u092C\u0930\u094B\u092C\u0930 \u0926\u093E\u092C\u093E",
  lineEditor_pointSelected: "\u092C\u093F\u0902\u0926\u0941 (\u090F\u0915 \u0915\u093F\u0935\u094D\u0939\u093E \u0905\u0928\u0947\u0915) \u0915\u093E\u0922\u093C\u0923\u094D\u092F\u093E \u0938\u093E\u0920\u0940 \u0921\u093F\u0932\u0940\u091F \u0915\u0940 \u0926\u093E\u092C\u093E,\nCtrlOrCmd \u092C\u0930\u094B\u092C\u093E\u0930 D \u092A\u094D\u0930\u0924\u093F \u0938\u093E\u0920\u0940,\n\u0915\u093F\u0935\u094D\u0939\u093E \u0921\u094D\u0930\u0947\u0917 \u0939\u0932\u0935\u0923\u094D\u092F\u093E \u0938\u093E\u0920\u0940",
  lineEditor_nothingSelected: "\u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0915\u0930\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940 \u090F\u0915 \u092C\u093F\u0902\u0926\u0942 \u0928\u093F\u0935\u0921\u093E (\u0905\u0928\u0947\u0915 \u0928\u093F\u0935\u0921\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940 SHIFT \u0927\u0930\u0942\u0928 \u0920\u0947\u0935\u093E),\n\u0915\u093F\u0902\u0935\u093E Alt \u0927\u0930\u0942\u0928 \u0920\u0947\u0935\u093E \u0906\u0923\u093F \u0928\u0935\u0940\u0928 \u092C\u093F\u0902\u0926\u0942 \u091C\u094B\u0921\u0923\u094D\u092F\u093E\u0938\u093E\u0920\u0940 \u0915\u094D\u0932\u093F\u0915 \u0915\u0930\u093E",
